"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[44672],{14036:(e,t,s)=>{s.r(t),s.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>u,frontMatter:()=>o,metadata:()=>n,toc:()=>c});const n=JSON.parse('{"id":"publicexpense","title":"","description":"2006/4/24 2043","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/publicexpense.md","sourceDirName":".","slug":"/publicexpense","permalink":"/en/publicexpense","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"publicexpense","title":"","hide_table_of_contents":true},"sidebar":"timelineSidebar","previous":{"title":"\u9f13\u5439\u6551\u4e16\u4e3b\u3001\u5927\u6551\u661f\u7684\u662f\u771f\u6b63\u7684\u7cbe\u795e\u9e26\u7247\uff01 (2006/4/23 18:32:41)","permalink":"/en/timeline/essays/spiritualopium"},"next":{"title":"\u4e2d\u56fd\u697c\u5e02\u80a1\u5e02\u7684\u95f9\u5267\uff0c\u90fd\u662f\u201c\u5927\u6551\u661f\u201d\u601d\u7ef4\u6d41\u6bd2\u6240\u81f4\uff01 (2006/4/24 21:08:18)","permalink":"/en/timeline/economics/saviour2"}}');var i=s(74848),a=s(28453);const o={id:"publicexpense",title:"",hide_table_of_contents:!0},r='Left-Wingers: The Capitalists\' Greatest Crime of Exploitation Has Become Your "Company Expense"?',l={},c=[];function h(e){const t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"left-wingers-the-capitalists-greatest-crime-of-exploitation-has-become-your-company-expense",children:'Left-Wingers: The Capitalists\' Greatest Crime of Exploitation Has Become Your "Company Expense"?'})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"2006/4/24 20:11:43"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:'Left-wingers have always been two-faced, saying one thing and meaning another. But even the cleverest fox shows its tail eventually. Today a certain leftist\'s post actually contained this line: "Private enterprises also have company-funded trips. I work in a capitalist enterprise, and the company has an annual budget for employees to go out and have fun." Left-wingers, the greatest proof of capitalist exploitation has become your company perks?'}),"\n",(0,i.jsx)(t.p,{children:'By leftist logic, surplus value is the greatest evidence of capitalist exploitation. So let us carefully analyze: what exactly does the "annual budget" mentioned by the leftist above consist of? Obviously, if this budget is merely the welfare rightfully belonging to each employee, then there\'s no question of "company expense" -- this so-called travel fund is simply each person\'s rightful welfare being held by the capitalist. In other words, this so-called travel fund is not each employee\'s welfare, and certainly not their wages. Anyone familiar with leftist economic trickery should see that this travel fund comes from the surplus value extracted by the capitalist from exploiting employees.'}),"\n",(0,i.jsx)(t.p,{children:'Surplus value, the greatest evidence of capitalist exploitation of workers, has somehow become a "company expense" in the mouths of leftists. Of course, leftists can swap concepts and argue that all surplus value, including travel funds, was created by workers, and therefore it\'s naturally a company expense. Even by this logic, workers should seize all surplus value from the capitalists, not wag their tails in glee over the scraps and leftovers of so-called travel funds tossed their way by capitalists. How is this different from the behavior of a certain domestic animal?'}),"\n",(0,i.jsx)(t.p,{children:'From this simple example, you can see that leftists are and will always be nothing but a bunch of blowhards. Beyond making some noise on the internet, in reality they live for the crumbs of charity the capitalists toss them from the surplus value they themselves created -- and the most shameless among them dress it up as "company expense." In other words, the leftists\' online bluster is merely the distorted result of their real-world situation. Leftist rhetoric shares a common origin with the commonplace ravings found in psychiatric wards. This is the true face of the left!'})]})}function u(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},28453:(e,t,s)=>{s.d(t,{R:()=>o,x:()=>r});var n=s(96540);const i={},a=n.createContext(i);function o(e){const t=n.useContext(a);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);